#include <cstdio>
#include <cstdlib>
#include <new>
static int g_order[16]; static int g_n = 0; static int g_freed = 0;
class CCharString { public: int id; ~CCharString() { g_order[g_n++] = id; } };
class CScriptInfo { public: void* AllocFunc; void* MasterScriptDataAlloc; CCharString Name; long ID; bool MasterScript; };
